import {plants,pots,lights,difficulties,sizes,questions,sizeOrder,sizePreferenceValues,plantTypes,filterPlants,plantGeometry} from './data.js';
import {getPlantMatch,rankPlants} from './recommendation.js';
import {read,write,fresh} from './storage.js';
import {rooms,chooseRoom,roomImageData} from './rooms.js';
import {analyzeImage} from './analysis.js';
let state=read(),question=0,answers={},spaceType='거실',pendingName='',editAnalysis=false,tab='plants',plantGroup='all',potColor='',potMaterial='',viz=null,toastTimer;
let introIndex=0,splashVisible=true;
const scenePixels=new WeakMap();
const expandedCards=new Map();
let galleryObserver=null;
let careDestination='/',photoBusy=false,analysisJob=null,analysisError='',analysisController=null,lastRoute='';
const activeSpace=()=>state.spaces.find(s=>s.id===state.activeSpaceId)||null;
const uploadSpace=()=>state.pendingSpace?null:activeSpace();
const newId=()=>crypto.randomUUID?.()||('id-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const app=document.querySelector('#app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,path,cls='btn')=>`<a class="${cls}" href="#${path}">${label}</a>`;
const photo=(space=activeSpace())=>space?.imageDataUrl||(space?.imageSource==='demo'?'assets/demo/room.png':null);
const member=()=>!!(state.signedIn&&state.account&&state.careProfile);
const ready=()=>activeSpace()?.analysisConfirmed&&member();
const match=p=>getPlantMatch(p,activeSpace(),member()?state.careProfile:null);
const ranked=()=>rankPlants(plants,activeSpace(),member()?state.careProfile:null);
const find=id=>plants.find(p=>p.id===id);
function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2800);}
function commit(next){try{write(next);state=next;return true;}catch{toast('저장하지 못했어요. 저장 공간을 확인해주세요.');return false;}}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
const icons={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',explore:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',saved:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 2 10 8 15 6-5 12-11 8-15z"/>',space:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M4 9h16M10 9v12"/>'};
function nav(route){return `<nav class="nav" aria-label="주 메뉴">${[['/','홈','home'],['/explore','탐색','explore'],['/saved','저장','saved'],['/my-page','마이페이지','space']].map(([path,label,icon])=>`<a href="#${path}" class="${route===path?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[icon]}</svg>${label}</a>`).join('')}</nav>`;}
function empty(title,description,cta='식물 탐색하기',path='/explore'){return `<div class="empty"><h2>${title}</h2><p>${description}</p>${link(cta,path,'btn secondary wide')}</div>`;}
function plantCard(p){
    const expanded=expandedCards.get(location.hash)===p.id,m=match(p);
    return `<article class="card gallery-card ${expanded?'is-expanded':''}"><div class="cardtop"><button class="gallery-photo" data-action="plant-preview:${p.id}" aria-expanded="${expanded}" aria-label="${p.name} ${expanded?'상세 보기':'간단히 보기'}"><img src="${p.image}" alt="${p.name}" loading="lazy"></button></div>${expanded?`<div class="cardbody"><button class="gallery-summary" data-action="plant-preview:${p.id}" aria-label="${p.name} 상세 보기"><h3>${p.name}</h3><div class="meta">${difficulties[p.difficulty]} · ${sizes[p.specimenSize]}</div></button>${m?`<small class="gallery-match">내 공간 적합도 ${m.score}점</small>${m.reasons.slice(0,2).map(r=>`<small class="reason">✓ ${r}</small>`).join('')}${m.cautions.length?`<small class="warn">△ ${m.cautions[0]}</small>`:''}`:''}<div class="gallery-actions">${link('자세히 보기','/plants/'+p.id,'btn secondary')}${link('내 공간에<br>놓아보기','/visualizer/'+p.id,'btn')}</div><div class="gallery-tools">${button(state.savedPlantIds.includes(p.id)?'♥ 저장됨':'♡ 저장','save:'+p.id,'text',`aria-pressed="${state.savedPlantIds.includes(p.id)}"`)}${button(state.comparePlantIds.includes(p.id)?'비교 취소':'＋ 비교','compare:'+p.id,'text',`aria-pressed="${state.comparePlantIds.includes(p.id)}"`)}</div></div>`:''}</article>`;
}
function bindGallery(){
    galleryObserver?.disconnect();
    if(typeof ResizeObserver==='undefined')return;
    const resize=card=>{const rows=Math.ceil((card.getBoundingClientRect().height+12)/16);card.style.gridRowEnd='span '+Math.max(1,rows);};
    galleryObserver=new ResizeObserver(entries=>entries.forEach(entry=>resize(entry.target)));
    document.querySelectorAll('.cards').forEach(grid=>{
        const cards=grid.querySelectorAll(':scope > .gallery-card');
        if(!cards.length)return;
        grid.classList.add('masonry-ready');bindVerticalGallery(grid);
        cards.forEach(card=>{resize(card);galleryObserver.observe(card);});
    });
}
function renderKeepingPosition(action){
    const top=window.scrollY,left=window.scrollX;
    render();
    document.querySelector(`[data-action="${action}"]`)?.focus({preventScroll:true});
    window.scrollTo({top,left,behavior:'instant'});
}

function header(route,title,onboarding){return `<header>${route==='/'?'<a href="#/" class="brand" aria-label="seekgoo 홈"><img src="assets/brand/logo-transparent.png" alt="seekgoo"></a>':`<button class="back" data-action="back" aria-label="뒤로">‹</button><span>${title}</span>`}${route==='/'?'<span class="header-spacer" aria-hidden="true"></span>':onboarding&&!['/auth','/signup','/profile/care','/space/result','/space/detail'].includes(route)?button('나가기',route==='/profile/care'?'care-exit':'exit','text'):'<span class="header-spacer" aria-hidden="true"></span>'}</header>`;}
function spacePicker(){return state.spaces.length?`<div class="space-picker" aria-label="공간 선택">${state.spaces.map(s=>`<button class="chip ${s.id===state.activeSpaceId?'active':''}" data-action="select-space:${s.id}" aria-pressed="${s.id===state.activeSpaceId}">${escape(s.name)}</button>`).join('')}${state.spaces.length<4?button('＋ 공간','new-space','text'):''}</div>`:'';}
function spaceBlocks(){return `<div class="space-blocks">${state.spaces.map(space=>`<button class="space-block ${space.id===state.activeSpaceId?'active':''}" data-action="space-info:${space.id}" aria-label="${escape(space.name)} 공간 정보 보기"><img src="${photo(space)}" alt="${escape(space.name)}"><span>${escape(space.name)}</span><small>${space.analysisConfirmed?lights[space.analysis.light]:'공간 정보 입력'}</small></button>`).join('')}${state.spaces.length<4?'<button class="space-block add-space" data-action="new-space"><span class="plus" aria-hidden="true">＋</span><span>공간 추가하기</span></button>':''}</div>`;}
function home(){
    const space=activeSpace(),recommendations=ready()?ranked():[];
    const personalized=recommendations.length>0;
    const list=personalized?recommendations.slice(0,3):plants.slice(0,6);
    return `<h1>나의 공간</h1>${!space?'<p>식물을 둘 공간을 등록해보세요</p>':''}${spaceBlocks()}<section aria-label="식물 둘러보기"><div class="sectionhead"><h2>${personalized?'이 공간과 잘 맞는 식물':'새로운 식구를 만나보세요'}</h2>${link('전체 보기',personalized?'/recommendations':'/explore','')}</div>${ready()&&!personalized?'<p>현재 조건에 맞는 추천 식물이 없어요. 다른 식물도 둘러보세요.</p>':''}${personalized?recommendationPodium(recommendations):`<div class="cards compact">${list.map(plantCard).join('')}</div>`}</section>`;
}

function setup(){const meta=state.pendingSpace;if(meta){spaceType=meta.type;pendingName=meta.name;}return `<span class="tiny">My space · ${state.spaces.length+1} / 4</span><h1>식물을 어디에<br>둘 예정인가요?</h1><p>같은 공간도 자리마다 따로 등록할 수 있어요.</p><div class="stack">${['거실','침실','작업실','베란다','기타'].map((v,i)=>`<button class="choice ${spaceType===v?'active':''}" data-action="type:${v}" aria-pressed="${spaceType===v}"><span>${['▱','▰','▤','▥','＋'][i]} &nbsp; ${v}</span><span>${spaceType===v?'✓':''}</span></button>`).join('')}</div><label for="space-name">공간 이름</label><input id="space-name" maxlength="30" placeholder="${spaceType==='기타'?'마당, 정원, 테라스, 현관 앞':'예: '+spaceType+' 창가'}" value="${escape(pendingName)}"><small>직접 이름을 붙여주세요. 비워두면 공간 종류를 이름으로 사용해요.</small>${button('다음 →','setup-next','wide')}`;}
function upload(){const space=uploadSpace(),type=state.pendingSpace?.type||space?.type||spaceType;return `<span class="tiny">Your room / ${escape(type)}</span><h1>식물이 머무를<br>자리를 담아주세요.</h1><p>창문과 식물을 둘 위치가 함께 보이면 좋아요.</p>${photo(space)?`<img class="room" src="${photo(space)}" alt="${escape(space.name)} 공간 사진"><div class="notice">사진을 바꾸면 이 공간에 저장한 조합의 배치가 초기화돼요.</div>`:'<div class="uploadbox"><h2>나의 공간을 담아주세요</h2><p>JPG · PNG · WebP</p></div>'}<input type="file" accept="image/jpeg,image/png,image/webp" id="photo-file" hidden><div class="photo-actions">${button(photo(space)?'사진 교체하기':'사진 선택','choose-photo','secondary',photoBusy?'disabled':'')}${button(photoBusy?'사진 준비 중…':photo(space)?'다시 촬영':'사진 촬영','camera','secondary',photoBusy?'disabled':'')}</div>${type==='기타'?'<small>마당, 정원, 테라스, 현관 앞 풍경을 담을 수 있어요.</small>':''}<p class="photo-privacy">사진은 외부로 전송하지 않고 이 기기에서 밝기를 분석해요.</p>${button('이 사진으로 분석하기','analyze','wide',!photo(space)||photoBusy?'disabled':'')}${photo(space)?link('공간 정보 직접 입력하기','/space/result','btn text wide'):''}`;}
function analysis(){const space=activeSpace(),a=space.analysis||{};return `<h1>${space.analysisCompleted?'공간을 살펴봤어요.':'공간 정보를 알려주세요.'}</h1><p>채광을 확인하고 필요한 정보를 입력해주세요.</p><img class="room" src="${photo()}" alt="${escape(space.name)} 공간 사진"><label for="light">채광 *</label><select id="light"><option value="">선택해주세요</option>${lights.map((l,i)=>`<option value="${i}" ${a.light===i?'selected':''}>${l}</option>`).join('')}</select><div class="temperature-field"><label for="temperature">온도 <span class="optional-label">선택</span></label><div class="temperature-input"><input id="temperature" type="number" min="-20" max="45" step="1" inputmode="numeric" aria-describedby="temperature-hint" placeholder="예: 22" value="${a.temperatureC??''}"><span>°C</span></div><small id="temperature-hint">−20~45 사이의 정수만 입력해주세요.<br>잘 모르겠다면 비워두셔도 괜찮아요.</small></div>${button('나에게 맞는 식구 추천받기','analysis-recommend','wide')}${button('저장하고 내 공간 보기','analysis-home','secondary wide')}${button('사진 다시 분석하기','analyze','text wide')}`;}
function saveAnalysis(){const light=document.querySelector('#light'),temp=document.querySelector('#temperature');if(light.value===''||!Number.isInteger(Number(light.value))||Number(light.value)<0||Number(light.value)>3){toast('채광을 선택해주세요.');light.focus();return false;}if(temp.validity?.badInput||!temp.checkValidity()||(temp.value!==''&&(!Number.isInteger(Number(temp.value))||Number(temp.value)<-20||Number(temp.value)>45))){toast('온도는 −20~45 사이의 정수로 입력해주세요.');temp.focus();return false;}const next=structuredClone(state),space=next.spaces.find(s=>s.id===next.activeSpaceId);space.analysis={light:Number(light.value),source:'manual',...(temp.value!==''?{temperatureC:Number(temp.value)}:{})};space.analysisConfirmed=true;return commit(next);}
function spaceDetail(){const space=activeSpace(),a=space.analysis||{};return `<h1>${escape(space.name)}</h1><img class="room" src="${photo()}" alt="${escape(space.name)}"><div class="metrics"><div class="metric"><small>채광</small><strong>${lights[a.light]||'미입력'}</strong></div><div class="metric metric-optional"><small>온도</small><strong>${a.temperatureC==null?'미입력':a.temperatureC+'°C'}</strong></div></div>${button('이 공간에 놓아보기','space-place:'+space.id,'wide')}${button('추천 식물 보기','recommend','secondary wide')}${link('공간 정보 수정','/space/result','btn text wide')}`;}
function questionnaire(){
    const labels=[['처음이에요','몇 번 실패했어요','익숙해요'],['거의 못 돌봐요','주 1회 정도','자주 돌봐요'],['물주기','햇빛','벌레','관리 난이도'],['초소형','소형','중형','대형','상관없어요']];
    const complete=questions.every(([key])=>answers[key]!=null),count=questions.filter(([key])=>answers[key]!=null).length;
    return `<section class="care-form"><span class="tiny">Care profile</span><h1>나의 식물 생활</h1><p>나와 가까운 답을 하나씩 골라주세요.</p><span class="care-count" role="status">${count} / 4 선택</span>${questions.map(([key,title,options],index)=>`<fieldset class="care-group"><legend><small>0${index+1}</small> ${title}</legend><div class="care-options">${options.map((_,i)=>{const value=key==='size'?sizePreferenceValues[i]:i;return `<button class="care-chip ${answers[key]===value?'active':''}" data-action="care-answer:${key}:${value}" aria-pressed="${answers[key]===value}">${labels[index][i]}</button>`;}).join('')}</div></fieldset>`).join('')}${button(state.signupDraft&&!member()?'가입하고 식구 만나기':'내 관리 성향 저장하기','care-submit','wide',complete?'':'disabled')}${member()?button('수정 취소','care-exit','text wide'):''}<small>마이페이지에서 언제든 수정할 수 있어요.</small></section>`;
}

function recommendationPodium(list){
    const top=list.slice(0,3);
    return `<section class="podium" aria-label="나에게 맞는 식물 순위">${top.map((p,i)=>`<a class="podium-plant rank-${i+1}" href="#/plants/${p.id}" aria-label="${i+1}등 ${p.name}, 적합도 ${p.match.score}점"><span class="rank-medal">${i+1}등</span><img src="${p.image}" alt="${p.name}"><strong>${p.name}</strong><span class="rank-score">${p.match.score}<small>점</small></span><small class="rank-reason">${escape(p.match.reasons[0]||'입력 조건 기준')}</small></a>`).join('')}</section><small class="rank-note">공간과 관리 성향을 기준으로 추천했어요.</small>`;
}
function careRadar(p){
    const light=(p.light.reduce((sum,l)=>sum+4-l,0)/p.light.length)/4;
    const values=[light,(p.difficulty+1)/4,[.25,.625,1][p.frequency],[.5,.75,1,.25][p.specimenSize]];
    const point=(i,v)=>[[150,142-86*v],[150+86*v,142],[150,142+86*v],[150-86*v,142]][i].join(',');
    const labels=[['채광',p.light.map(i=>lights[i]).join(' · ')],['난이도',difficulties[p.difficulty]],['물 관리',['드물게 확인','주기적으로 확인','자주 확인'][p.frequency]],['크기',sizes[p.specimenSize]]];
    return `<section class="care-chart"><h2>관리 한눈에 보기</h2><svg viewBox="0 0 300 280" role="img" aria-label="${escape(labels.map(([name,value])=>name+': '+value).join(', '))}">${[.25,.5,.75,1].map(v=>`<polygon class="radar-grid" points="${values.map((_,i)=>point(i,v)).join(' ')}"/>`).join('')}<path class="radar-axis" d="M150 56V228 M64 142H236"/><polygon class="radar-value" points="${values.map((v,i)=>point(i,v)).join(' ')}"/>${values.map((v,i)=>`<circle class="radar-dot" cx="${point(i,v).split(',')[0]}" cy="${point(i,v).split(',')[1]}" r="4"/>`).join('')}<text x="150" y="28" text-anchor="middle">채광</text><text x="252" y="147" text-anchor="middle">난이도</text><text x="150" y="257" text-anchor="middle">물 관리</text><text x="38" y="147" text-anchor="middle">크기</text></svg><dl class="radar-labels">${labels.map(([name,value])=>`<div><dt>${name}</dt><dd>${value}</dd></div>`).join('')}</dl></section>`;
}
function recommendations(){const list=ranked();return `<span class="tiny">Grow fit / Curated for you</span><h1>${escape(activeSpace().name)}에서 함께할<br>식구를 찾았어요.</h1><p>공간 환경과 관리 성향을 함께 고려했어요.</p><div class="row"><span class="badge">${lights[activeSpace().analysis.light]} · ${questions[1][2][state.careProfile.frequency]}</span>${link('수정','/my-page','muted')}</div>${list.length?`${recommendationPodium(list)}${list.length>3?`<h2>함께 살펴볼 식물</h2><div class="cards compact">${list.slice(3).map(plantCard).join('')}</div>`:''}`:empty('현재 조건에 맞는 추천 식물이 없어요','공간 조건을 수정하거나 전체 식물을 둘러보세요.','조건 수정','/space/result')}${link('전체 식물 탐색하기','/explore','btn secondary wide')}`;}
const filterDefinitions=[['types','종류',plantTypes.map(v=>[v,v])],['light','채광',lights.map((v,i)=>[i,v])],['difficulty','난이도',difficulties.map((v,i)=>[i,v])],['size','크기',sizeOrder.map(i=>[i,sizes[i]])],['features','특징',['건조에 강함','습도 선호','잎 감상','꽃 감상','열매 감상'].map(v=>[v,v])]];
const filtersFor=scope=>scope==='viz'?state.visualizerFilters:state.exploreFilters;
function filtered(){return filterPlants(plants,state.exploreFilters);}
function filterPanel(scope){const f=filtersFor(scope),prefix=scope==='viz'?'viz-':'',id=scope==='viz'?'viz-search':'search',count=filterDefinitions.reduce((n,[key])=>n+f[key].length,0);return `<div class="plant-filter-panel"><label for="${id}">식물 이름 검색</label><input id="${id}" type="search" placeholder="식물 이름을 검색해보세요" value="${escape(f.query)}"><details id="${scope}-filters"><summary>필터${count?` · ${count}개 선택`:""}<span class="filter-hint">종류 · 채광 · 난이도 · 크기 · 특징</span></summary><div class="filter-options" tabindex="0" aria-label="식물 필터 옵션">${filterDefinitions.map(([key,label,options])=>`<fieldset class="filter-group"><legend>${label}</legend><div class="filters">${options.map(([v,text])=>`<button class="chip ${f[key].includes(v)?'active':''}" aria-pressed="${f[key].includes(v)}" data-action="${prefix}filter:${key}:${v}">${text}</button>`).join('')}</div></fieldset>`).join('')}<small>크기는 사진 속 개체를 기준으로 보며, 성장에 따라 달라질 수 있어요.</small></div></details></div>`;}
function filterSummary(scope,count){const f=filtersFor(scope),prefix=scope==='viz'?'viz-':'';return `<div class="filters">${filterDefinitions.flatMap(([key,label,options])=>f[key].map(v=>`<button class="chip active" data-action="${prefix}filter:${key}:${escape(v)}">${escape(options.find(([value])=>value===v)?.[1]||v)} ×</button>`)).join('')}</div><div class="sectionhead"><p role="status">식물 ${count}개</p>${button('필터 초기화',prefix+'filters-clear','text')}</div>`;}
function explore(){return `<span class="tiny">MY seekgoo of destiny</span><h1>새로운 내 식구 찾기</h1>${filterPanel('explore')}<div id="explore-results">${exploreResults()}</div>`;}
function exploreResults(){const list=filtered();return `${filterSummary('explore',list.length)}<div class="cards compact">${list.length?list.map(plantCard).join(''):`<div class="empty"><h2>조건에 맞는 식물이 없어요</h2><p>검색어나 필터를 바꿔보세요.</p>${button('필터 초기화','filters-clear','secondary wide')}</div>`}</div>`;}
function visualizerPlantResults(){const list=plantGroup==='saved'?plants.filter(p=>state.savedPlantIds.includes(p.id)):plantGroup==='recommended'?ranked():filterPlants(plants,state.visualizerFilters);return `${plantGroup==='all'?filterSummary('viz',list.length):''}<div class="selector" tabindex="0" aria-label="좌우로 넘겨서 선택하기">${list.length?list.map(p=>`<button class="${viz.plantId===p.id?'active':''}" data-action="viz-plant:${p.id}" aria-pressed="${viz.plantId===p.id}"><img src="${p.image}" alt="">${p.name}<br><small>${sizes[p.specimenSize]}</small>${match(p)?`<br><small>${match(p).score}점</small>`:''}</button>`).join(''):`<div class="selector-empty"><p>조건에 맞는 식물이 없어요.</p>${plantGroup==='all'?button('필터 초기화','viz-filters-clear','secondary'):button('전체 식물 보기','plant-group:all','secondary')}</div>`}</div>`;}
function refreshVizResults(){document.querySelector('#visualizer-results').innerHTML=visualizerPlantResults();bindHorizontalScroll(document.querySelector('.selector'));}
function detail(p){const m=match(p),tipKeys=['watering','light','pests','difficulty'],preferred=member()?tipKeys[state.careProfile.concern]:null,tipOrder=[...new Set([preferred,...tipKeys].filter(Boolean))];return `<div class="detail-image"><img src="${p.image}" alt="${p.name}"></div><span class="tiny">${p.english}</span><div class="row"><h1>${p.name}</h1><button class="icon ${state.savedPlantIds.includes(p.id)?'active':''}" aria-label="식물 저장" aria-pressed="${state.savedPlantIds.includes(p.id)}" data-action="save:${p.id}">${state.savedPlantIds.includes(p.id)?'♥':'♡'}</button></div><p>${p.description}</p><div class="filters">${p.types.map(type=>`<span class="badge">${type}</span>`).join('')}</div>${careRadar(p)}${m?`<div class="cardbody card"><div class="row"><h3>내 공간 적합도</h3><span class="score">${m.score}점</span></div><small>입력 조건 기준 적합도</small>${m.reasons.map(r=>`<p class="reason">✓ ${r}</p>`).join('')}${m.cautions.map(r=>`<p class="warn">△ ${r}</p>`).join('')}</div>`:`<div class="notice">${!member()?'관리 성향 테스트가 완료되지 않아 매칭 점수가 표시되지 않아요. 공간에 놓아보기는 바로 이용할 수 있어요.':'공간 정보를 확인하면 매칭 점수를 볼 수 있어요.'}</div>`}${link('내 공간에 놓아보기 ↗','/visualizer/'+p.id,'btn wide')}${button(state.comparePlantIds.includes(p.id)?'비교에서 빼기':'비교하기',`compare:${p.id}`,'secondary wide')}<h2>함께 지내는 방법</h2>${tipOrder.map(k=>`<details ${k===preferred?'open':''}><summary>${{watering:'물주기',light:'햇빛과 위치',pests:'잎 상태 살피기',difficulty:'관리 팁'}[k]}${k===preferred?' · 나의 걱정':''}</summary><p>${p.concernTips[k]}</p></details>`).join('')}`;}
function compare(){const list=state.comparePlantIds.map(find).filter(Boolean);if(!list.length)return empty('비교할 식물을 골라주세요','탐색이나 상세에서 비교 버튼을 눌러보세요.');const rows=[['내 공간 적합도',p=>{const m=match(p);return m?m.score+'점':'—';}],['난이도',p=>difficulties[p.difficulty]],['채광',p=>p.light.map(i=>lights[i]).join(' · ')],['물 관리',p=>['드물게 확인','주기적으로 확인','자주 확인'][p.frequency]],['크기',p=>sizes[p.specimenSize]],['물주기',p=>p.watering],['특징',p=>p.features.join(' · ')],['나와의 관리 궁합',p=>{const m=match(p);return m?[...m.reasons,...m.cautions].join(' / '):'공간과 관리 성향 입력 후 확인';}]];return `<div class="sectionhead"><h1>식물 비교</h1><span class="badge">${list.length} / 3</span></div><p>같은 항목끼리 나란히 살펴보세요.</p><div class="comparison-scroll" tabindex="0" role="region" aria-label="식물 비교표"><table class="comparison-table"><thead><tr><th scope="col">비교 항목</th>${list.map(p=>`<th scope="col"><div class="compare-photo"><a href="#/plants/${p.id}"><img src="${p.image}" alt="${p.name}"></a>${button('−','compare:'+p.id,'compare-remove',`aria-label="${p.name} 비교에서 제거"`)}</div>${link(p.name,'/plants/'+p.id,'compare-name')}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${escape(value(p))}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">미리 배치</th>${list.map(p=>`<td>${link('놓아보기','/visualizer/'+p.id,'btn secondary')}</td>`).join('')}</tr></tbody></table></div>${list.length<3?link('＋ 식물 추가','/explore','btn secondary wide'):''}`;}

const pos=(i,cols,rows)=>`${(i%cols)/(cols-1)*100}% ${Math.floor(i/cols)/(rows-1)*100}%`;
function composition(v,interactive=false){const p=find(v.plantId)||plants[0],pot=pots.find(p=>p.id===v.potId)||pots[0],soil=pot.soil??[.285,.265,.29,.16,.18,.19][pot.atlas],lip=pot.lip??[.33,.30,.34,.20,.23,.25][pot.atlas],cut=p.sheet||p.id==='p10'?1:[.96,.96,.98,.98,.95,.94,.98,.98,.98,.98,1,1][p.atlas],overhang=p.overhang||p.id==='p06',plantClass=p.id==='p10'?'lucky-cutout':p.sheet?'plant-sheet-'+p.sheet:'',potClass=pot.sheet?'additional-pot':'',geometry=plantGeometry(p);return `<div class="composition ${overhang?'overhang':''}" ${interactive?'id="composition" tabindex="0" role="group" aria-label="식물 배치. 방향키로 이동할 수 있어요"':''} style="left:${v.transform.x*100}%;top:${v.transform.y*100}%;width:${44*geometry.scene*v.transform.scale}%;--ground-top:${((1-.58*soil)+.58*pot.base)/1.37*100}%;--ground-center:${(0.21+.58*pot.baseCenter)*100}%;--contact-width:${.58*pot.baseWidth*100}%;--plant-width:${geometry.width}%;--pot-top:${(1-.58*soil)/1.37*100}%;--front-lip:${lip*100}%;--plant-top:${geometry.top}%;--plant-cut:${(1-cut)*100}%;--plant-left:${geometry.left}%"><div class="composition-objects"><div class="pot-layer pot-back ${potClass}" style="background-position:${pos(pot.atlas,pot.sheet?4:3,2)}"></div><div class="plant-layer ${plantClass}" style="background-position:${p.id==='p10'?'center':pos(p.atlas,p.sheet?3:4,p.sheet?2:3)}"></div><div class="pot-layer pot-front ${potClass}" style="background-position:${pos(pot.atlas,pot.sheet?4:3,2)}"></div></div></div>`;}

function canvas(v,interactive=false){const space=state.spaces.find(s=>s.id===v.spaceId)||activeSpace();return `<div class="canvas" ${interactive?'id="canvas"':''}><img class="background" src="${photo(space)}" alt="${escape(space?.name)} 공간 사진">${composition(v,interactive)}</div>`;}
function visualizer(id){if(!ready()&&plantGroup==='recommended')plantGroup='all';if(!viz||viz.entry!==id||viz.spaceId!==state.activeSpaceId)viz={entry:id,spaceId:state.activeSpaceId,plantId:find(id)?.id||plants[0].id,potId:pots[0].id,transform:{x:.5,y:.65,scale:1}};const selected=find(viz.plantId),pot=pots.find(p=>p.id===viz.potId);return `<span class="tiny">Style fit / In your room</span><h1>우리 집에 놓아볼까요?</h1>${spacePicker()}<p>식물을 끌어 옮기고 크기를 조절해보세요.</p>${canvas(viz,true)}<p class="placement-note">식물별 상대 크기를 반영했어요. 사진 속 실제 치수와 원근감을 측정한 이미지는 아니므로 배치 참고용으로 봐주세요.</p><div class="sectionhead"><h2>${selected.name} <small>${sizes[selected.specimenSize]}</small></h2><small>${pot.name}</small></div><div class="filters">${button('식물 선택','tab:plants',tab==='plants'?'':'secondary')}${button('화분 선택','tab:pots',tab==='pots'?'':'secondary')}</div>${tab==='plants'?`<div class="filters">${[...(ready()?[['recommended','추천 식물']]:[]),['saved','저장한 식물'],['all','전체 식물']].map(([v,l])=>`<button class="chip ${plantGroup===v?'active':''}" data-action="plant-group:${v}">${l}</button>`).join('')}</div>${plantGroup==='all'?filterPanel('viz'):''}<div id="visualizer-results">${visualizerPlantResults()}</div>`:`<div class="row"><div><label for="pot-color">색상</label><select id="pot-color"><option value="">전체</option>${[...new Set(pots.map(p=>p.color))].map(v=>`<option ${potColor===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="pot-material">재질</label><select id="pot-material"><option value="">전체</option>${[...new Set(pots.map(p=>p.material))].map(v=>`<option ${potMaterial===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="selector" tabindex="0" aria-label="좌우로 넘겨서 선택하기">${pots.filter(p=>(!potColor||potColor===p.color)&&(!potMaterial||potMaterial===p.material)).map(p=>`<button class="${viz.potId===p.id?'active':''}" data-action="viz-pot:${p.id}"><div class="pot-thumb ${p.sheet?'additional-pot':''}" style="background-position:${pos(p.atlas,p.sheet?4:3,2)}"></div>${p.name}</button>`).join('')||'<p>조건에 맞는 화분이 없어요.</p>'}</div>`}<div class="controls"><div class="row"><label for="scale">크기 <output id="scale-label">${Math.round(viz.transform.scale*100)}%</output></label>${button('위치 초기화','viz-reset','text')}</div><div class="row">${button('−','scale-down','secondary','aria-label="크기 줄이기"')}<input id="scale" type="range" min="0.5" max="1.5" step="0.05" value="${viz.transform.scale}" aria-label="식물 크기">${button('＋','scale-up','secondary','aria-label="크기 늘리기"')}</div></div>${button('이 조합 저장하기','save-combo','wide')}`;}
function combinations(spaceId=null){return state.savedCombinations.filter(c=>(!spaceId||c.spaceId===spaceId)&&state.spaces.some(s=>s.id===c.spaceId)).map(c=>`<article class="combo">${canvas(c)}<span class="badge">${escape(state.spaces.find(s=>s.id===c.spaceId).name)}</span><div class="row" style="margin-top:12px"><strong>${find(c.plantId).name}</strong><small>${pots.find(p=>p.id===c.potId).name}</small></div>${c.placementNeedsReview?'<p class="warn">사진이 바뀌어 배치를 다시 확인해주세요.</p>':''}<div class="row">${button('배치 열기','open-combo:'+c.id,'text')}${button('삭제','delete-combo:'+c.id,'text')}</div></article>`).join('')||empty('아직 저장한 조합이 없어요','식물 상세에서 내 공간에 놓아보세요.');}
function saved(){return `<span class="tiny">Your shortlist</span><h1>마음에 담은 식구</h1><h2>저장한 식물 <small>${state.savedPlantIds.length}</small></h2><div class="cards compact">${state.savedPlantIds.map(id=>plantCard(find(id))).join('')||empty('아직 저장한 식물이 없어요','마음에 드는 식물의 하트를 눌러주세요.')}</div><h2>저장한 조합 <small>${state.savedCombinations.length}</small></h2>${combinations()}`;}
function mySpace(){const profile=member()?state.careProfile:null;return `<h1>마이페이지</h1><section class="profile-summary">${member()?`<p class="member-name">${escape(state.account.username)} 님, 반가워요.</p><div class="sectionhead"><h2>나의 관리 성향</h2>${button('수정','care-edit','text')}</div><p>${questions[0][2][profile.experience]} · ${questions[1][2][profile.frequency]}</p><div class="filters"><span class="badge">${questions[2][2][profile.concern]}이 걱정돼요</span><span class="badge">${profile.size===3?'크기는 상관없어요':sizes[profile.size===4?3:profile.size]+'을 좋아해요'}</span></div>${button('로그아웃','logout','text')}`:`<h2>내 정보</h2><p>로그인하면 나에게 꼭 맞는 식물을 찾아드려요</p>${link('로그인하기','/auth','btn wide')}`}</section><div class="sectionhead"><h2>나의 공간 <small>${state.spaces.length} / 4</small></h2>${state.spaces.length<4?button('＋ 등록','new-space','text'):''}</div>${state.spaces.length?state.spaces.map(space=>`<article class="space-card"><img class="room" src="${photo(space)}" alt="${escape(space.name)}"><div class="sectionhead"><h3>${escape(space.name)}</h3><span class="badge">${space.analysisConfirmed?lights[space.analysis.light]:'정보 입력'}</span></div><small>${escape(space.type)} · 저장 조합 ${state.savedCombinations.filter(c=>c.spaceId===space.id).length}</small><div class="space-actions">${button('공간 정보','space-info:'+space.id,'secondary')}${button('사진 교체','space-photo:'+space.id,'secondary')}${button('이름 수정','rename-space:'+space.id,'text')}${button('삭제','delete-space:'+space.id,'text')}</div>${button('이 공간에 놓아보기','space-place:'+space.id,'wide')}</article>`).join(''):empty('식구를 들일 자리를 알려주세요','최대 4개의 공간을 등록할 수 있어요.','내 공간 등록하기','/space/new')}<h2>저장한 조합</h2>${combinations()}`;}
function startNewSpace(){if(state.spaces.length>=4){toast('공간은 최대 4개까지 등록할 수 있어요.');return;}const next=structuredClone(state);next.pendingSpace={id:newId(),type:'거실',name:''};if(commit(next)){spaceType='거실';pendingName='';go('/space/new');}}
function selectSpace(id){if(!state.spaces.some(s=>s.id===id))return false;const next=structuredClone(state);next.activeSpaceId=id;next.pendingSpace=null;if(commit(next)){viz=null;editAnalysis=false;return true;}return false;}
function beginCare(destination='/'){careDestination=destination;answers={...((member()?state.careProfile:state.careDraft)||{})};question=member()?0:Math.max(0,questions.findIndex(([k])=>answers[k]==null));go('/profile/care');}
function requestRecommendation(){if(!member()){go('/auth');return;}if(!activeSpace()){startNewSpace();return;}if(!activeSpace().analysisConfirmed){go('/space/result');return;}go('/recommendations');}
function analysisLoading(){return analysisError?`<div class="loading"><span class="tiny">Your space</span><h1>사진을 확인하지<br>못했어요.</h1><p role="alert">${escape(analysisError)}</p>${button('다시 분석하기','analyze','wide')}${button('공간 정보 직접 입력하기','analysis-manual','secondary wide')}${link('사진 바꾸기','/space/photo','btn text wide')}</div>`:`<section class="space-scan" role="status" aria-live="polite"><h1>공간 분석 중입니다</h1><p>사진의 밝기를 확인하고 있어요.</p><div class="scan-photo"><img src="${photo()}" alt="${escape(activeSpace()?.name)} 분석 중인 공간"><div class="scan-grid" aria-hidden="true"></div><div class="scan-line" aria-hidden="true"></div><span class="scan-caption">밝기 · 명암 분포 확인 중</span></div><div class="scan-indicator" aria-hidden="true"><span></span><span></span><span></span></div><p class="scan-note">잠시 후 결과를 확인하고 수정할 수 있어요.</p>${button('취소하고 홈으로','exit','text wide')}</section>`;}

function intro(){const slides=[['01 / YOUR SPACE','나의 공간을<br>등록해보세요','어디에 식구를 들이실건가요?<br>식물을 둘 공간을 사진으로 담아주세요.'],['02 / YOUR PLANT','나에게 딱 맞는<br>식물을 찾아보세요','공간의 빛과 나의 관리 성향으로<br>함께 지내기 좋은 식물을 찾아드려요.'],['03 / YOUR PREVIEW','내 공간에<br>미리 놓아보세요','마음에 드는 식물과 화분을 골라<br>어디에 어울릴지 확인해보세요.']];return `<section class="welcome"><div class="welcome-top"><span class="tiny">Meet your seekgoo</span>${button('건너뛰기','intro-finish','text')}</div><div class="intro-slides" tabindex="0" role="region" aria-label="식구 소개. 좌우로 밀어서 넘겨주세요">${slides.map(([step,title,copy],i)=>`<article class="intro-slide" aria-label="${i+1} / 3"><div class="intro-art art-${i}">${i===0?'<img draggable="false" src="assets/demo/room.png" alt="식물을 놓을 밝은 실내 공간">':i===1?'<img draggable="false" src="assets/plants/ref-4.png" alt="햇빛을 받은 몬스테라">':`<img draggable="false" src="assets/demo/room.png" alt="식물이 놓인 우리 집 미리보기">${composition({plantId:'p05',potId:'pot0',transform:{x:.54,y:.7,scale:1.1}})}`}</div><span class="tiny intro-step">${step}</span><h1>${title}</h1><p>${copy}</p>${i===2?button('식구 시작하기 →','intro-finish','wide'):''}</article>`).join('')}</div><div class="intro-bottom"><div class="intro-dots" aria-label="소개 페이지">${slides.map((_,i)=>`<button data-action="intro-page:${i}" class="${i===introIndex?'active':''}" aria-label="${i+1}번째 소개" aria-current="${i===introIndex?'step':'false'}"></button>`).join('')}</div><small>좌우로 넘겨보세요 ↔</small></div></section>`;}

function auth(){return `<section class="auth-page"><span class="tiny">Meet your green</span><h1>나의 운명의 식구,<br>여기서 만나요</h1><div class="auth-art"><img src="assets/plants/ref-0.png" alt="동그란 잎의 필레아"></div><p>당신의 일상에 함께할<br>나만의 식구를 찾아드릴게요.</p>${link('로그인하고 SEEKGOO 추천받기',state.account?'/login':'/signup','btn wide')}${button('먼저 둘러보기','browse','secondary wide')}${state.signupDraft&&!state.account?button('작성하던 가입 이어하기','resume-signup','text wide'):''}${!state.account?link('이미 아이디가 있어요','/login','btn text wide'):''}</section>`;}
function signup(){if(state.account)return login();return `<span class="tiny">Welcome to seekgoo</span><h1>식구가 되어주세요.</h1><p>아이디를 만들고 나의 관리 성향을 알려주세요.</p><form id="signup-form"><label for="username">아이디</label><input id="username" name="username" autocomplete="username" minlength="1" maxlength="20" required pattern="[A-Za-z0-9가-힣_]{1,20}" placeholder="식구에서 사용할 이름" value="${escape(state.signupDraft?.username||'')}"><small>한글·영문·숫자·밑줄, 1~20자</small><div class="agreements"><label><input type="checkbox" id="agree-service" required ${state.signupDraft?'checked':''}> [필수] 서비스 이용 동의</label><details><summary>내용 보기</summary><p>식물 정보와 배치 이미지는 식물을 선택하기 위한 참고 정보입니다. 내 공간과 식물 상태를 확인하며 이용해주세요.</p></details><label><input type="checkbox" id="agree-storage" required ${state.signupDraft?'checked':''}> [필수] 정보 저장 동의</label><details><summary>내용 보기</summary><p>아이디, 관리 성향, 공간 사진과 저장한 식구는 이 브라우저에 저장됩니다. 브라우저 데이터를 삭제하면 함께 삭제됩니다. 사진 밝기 분석은 이 기기 안에서 처리되며 사진을 외부로 전송하지 않습니다.</p></details></div><button type="submit" class="btn wide">동의하고 나의 관리 성향 알아보기</button></form>`;}
function login(){return `<span class="tiny">Welcome back</span><h1>다시 만나 반가워요.</h1><p>이전에 만든 아이디로 들어오세요.</p><form id="login-form"><label for="login-id">아이디</label><input id="login-id" autocomplete="username" required maxlength="20" placeholder="나의 아이디"><button class="btn wide" type="submit">로그인</button></form>${!state.account?link('아이디 만들기','/signup','btn secondary wide'):''}${button('먼저 둘러보기','browse','text wide')}`;}
function finishIntro(){const next=structuredClone(state);next.introSeen=true;if(commit(next))go('/auth');}
function startSignup(){const input=document.querySelector('#username');if(!/^[A-Za-z0-9가-힣_]{1,20}$/.test(input.value)){toast('아이디는 한글·영문·숫자·밑줄로 1~20자를 입력해주세요.');input.focus();return;}if(!input.checkValidity()){input.reportValidity();return;}if(!document.querySelector('#agree-service').checked||!document.querySelector('#agree-storage').checked){toast('필수 항목에 동의해주세요.');return;}const next=structuredClone(state);next.signupDraft={username:input.value.trim(),agreedAt:new Date().toISOString()};next.careDraft={};if(commit(next)){answers={};question=0;careDestination='/';go('/profile/care');}}
function signIn(){const id=document.querySelector('#login-id').value.trim();if(!state.account||state.account.username!==id){toast('이 브라우저에 저장된 아이디를 확인해주세요.');return;}const next=structuredClone(state);next.signedIn=true;if(commit(next))go('/');}

function render(){const route=location.hash.slice(1)||'/';if(route==='/profile/care'&&!member()&&!state.signupDraft){go('/auth');return;}if(lastRoute==='/space/analyzing'&&route!=='/space/analyzing'){analysisController?.abort();analysisController=null;analysisJob=null;analysisError='';}if(route==='/my-space'){go('/my-page');return;}if(route==='/space/new'&&state.spaces.length>=4){toast('공간은 최대 4개까지 등록할 수 있어요.');go('/my-page');return;}if(route==='/space/new'&&!state.pendingSpace){startNewSpace();return;}if(['/space/result','/space/analyzing','/space/detail'].includes(route)&&!photo()){go('/space/photo');return;}if(route==='/recommendations'&&!ready()){requestRecommendation();return;}if(route==='/profile/care'&&lastRoute!==route&&Object.keys(answers).length===0){answers={...((member()?state.careProfile:state.careDraft)||{})};question=Math.max(0,questions.findIndex(([k])=>answers[k]==null));}lastRoute=route;let title='',body='',onboarding=/^\/space|^\/profile|^\/intro|^\/auth|^\/signup|^\/login/.test(route);
if(route==='/intro'){title='식구 소개';body=intro();}else if(route==='/auth'){title='식구 시작하기';body=auth();}else if(route==='/signup'){title='회원가입';body=signup();}else if(route==='/login'){title='로그인';body=login();}else if(route==='/')body=home();else if(route==='/space/new'){title='공간 등록';body=setup();}else if(route==='/space/photo'){title='공간 사진';body=upload();}else if(route==='/space/analyzing'){title='공간 분석';body=analysisLoading();}else if(route==='/space/detail'){title='내 공간';body=spaceDetail();}else if(route==='/space/result'){title='공간 정보';body=analysis();}else if(route==='/profile/care'){title='나의 관리 성향';body=questionnaire();}else if(route==='/recommendations'){title='맞춤 추천';body=recommendations();}else if(route==='/explore'){title='식물 탐색';body=explore();}else if(route.startsWith('/plants/')){const p=find(route.split('/')[2]);title='식물 상세';body=p?detail(p):empty('식물을 찾을 수 없어요','다른 식물을 둘러보세요.');}else if(route==='/compare'){title='식물 비교';body=compare();}else if(route.startsWith('/visualizer')){title='내 공간에 놓아보기';body=photo()?visualizer(route.split('/')[2]):empty('공간 사진이 필요해요','나의 공간 사진 위에 식물을 놓아볼 수 있어요.','내 공간 등록하기','/space/new');}else if(route==='/saved'){title='저장';body=saved();}else if(route==='/my-page'){title='마이페이지';body=mySpace();}else if(route==='/success'){title='조합 저장';body=`<div class="success"><div class="success-mark">✓</div><h1>조합을 저장했어요.</h1><p>마음에 드는 풍경을 언제든 다시 꺼내보세요.</p>${viz?canvas(viz):''}${link('저장한 조합 보기','/saved','btn wide')}${link('다른 조합 만들어보기','/visualizer/'+(viz?.plantId||plants[0].id),'btn secondary wide')}${link('식물 상세로 돌아가기','/plants/'+(viz?.plantId||plants[0].id),'btn secondary small-return wide')}${link('홈으로 돌아가기','/','btn secondary small-return wide')}</div>`;}else{go('/');return;}
app.innerHTML=(splashVisible?'<div class="splash" role="status" aria-label="식구를 준비하고 있어요"><img src="assets/brand/logo-transparent.png" alt="seekgoo"><p>Find your plant. Meet your seekgoo.</p></div>':'')+(route==='/intro'?'':header(route,title,onboarding))+`<main>${body}</main>`+(!onboarding?nav(route):'')+(route==='/explore'&&state.comparePlantIds.length?`<a class="tray row" href="#/compare"><span>비교해보기</span><span>${state.comparePlantIds.length}/3</span></a>`:'');bindGallery();bindSceneLighting();if(route.startsWith('/visualizer')&&photo()){bindDrag();bindHorizontalScroll(document.querySelector('.selector'));}if(route==='/intro')bindIntro();if(route==='/space/analyzing'&&!analysisJob&&!analysisError)void performAnalysis();}
function analysisPause(signal){
    return new Promise(resolve=>{
        if(signal.aborted){resolve();return;}
        const done=()=>{clearTimeout(timer);signal.removeEventListener('abort',done);resolve();};
        const timer=setTimeout(done,1700);
        signal.addEventListener('abort',done,{once:true});
    });
}
async function performAnalysis(){const space=activeSpace();if(!space||analysisJob)return;const controller=new AbortController();analysisController=controller;const job={id:space.id,revision:space.photoRevision};analysisJob=job;
 try{const [result]=await Promise.all([analyzeImage(photo(space),space.type,controller.signal),analysisPause(controller.signal)]);if(controller.signal.aborted||analysisJob!==job)return;const next=structuredClone(state),target=next.spaces.find(s=>s.id===job.id);if(!target||target.photoRevision!==job.revision)return;target.analysis={...result,...(target.analysis?.temperatureC!=null?{temperatureC:target.analysis.temperatureC}:{})};target.analysisConfirmed=false;target.analysisCompleted=true;if(commit(next)){editAnalysis=false;go('/space/result');}else{analysisError='결과를 저장하지 못했어요. 저장 공간을 확인해주세요.';render();}}
 catch(error){if(controller.signal.aborted)return;analysisError=error.message||'사진을 분석하지 못했어요.';render();}
}
async function savePhoto(src,room=null,context=null){const next=structuredClone(state),meta=context?.meta||next.pendingSpace;const old=context?next.spaces.find(s=>s.id===context.id):meta?null:activeSpace();if(context?.id&&!old){toast('공간이 변경되었어요. 다시 선택해주세요.');return;}if(!old&&next.spaces.length>=4){toast('공간은 최대 4개까지 등록할 수 있어요.');return;}const space={...(old||{}),id:old?.id||meta?.id||newId(),name:old?.name||meta?.name||meta?.type||'거실',type:old?.type||meta?.type||'거실',imageSource:room?'capture':'upload',imageDataUrl:src,captureAssetId:room?.id||null,photoRevision:(old?.photoRevision||0)+1,analysis:{...(old?.analysis?.temperatureC!=null?{temperatureC:old.analysis.temperatureC}:{})},analysisCompleted:false,analysisConfirmed:false};delete space.demoAssetId;next.spaces=old?next.spaces.map(s=>s.id===old.id?space:s):[...next.spaces,space];next.activeSpaceId=space.id;next.pendingSpace=null;next.savedCombinations=next.savedCombinations.map(c=>c.spaceId===space.id?{...c,transform:{x:.5,y:.65,scale:1},placementNeedsReview:true}:c);try{write(next);state=next;viz=null;pendingName='';editAnalysis=false;render();toast('공간 사진을 저장했어요.');return true;}catch{toast('사진을 저장하지 못했어요. 더 작은 사진을 선택해주세요.');return false;}}
function photoContext(){return state.pendingSpace?{meta:structuredClone(state.pendingSpace)}:{id:activeSpace()?.id};}
async function capturePhoto(){if(photoBusy)return;const context=photoContext(),space=uploadSpace(),type=context.meta?.type||space?.type||'거실',room=chooseRoom(type,space?.captureAssetId);photoBusy=true;render();try{const data=await roomImageData(room);await savePhoto(data,room,context);}catch{toast('사진을 준비하지 못했어요. 다시 촬영해주세요.');}finally{photoBusy=false;render();}}
async function uploadFile(file){if(!file||photoBusy)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('JPG, PNG, WebP 사진을 선택해주세요.');return;}const context=photoContext();photoBusy=true;render();try{if(file.size>30*1024*1024)throw Error();const bitmap=await createImageBitmap(file),ratio=Math.min(1,1000/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*ratio));c.height=Math.max(1,Math.round(bitmap.height*ratio));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();await savePhoto(c.toDataURL('image/jpeg',.72),null,context);}catch{toast('사진을 열지 못했어요. 다른 사진으로 다시 시도해주세요.');}finally{photoBusy=false;render();}}


// Keep the horizontal browsing position and keyboard focus when changing an item.
function renderSelection(action){
 const left=document.querySelector('.selector')?.scrollLeft||0;
 const filterOpen=document.querySelector('#viz-filters')?.open;
 const top=window.scrollY;
 render();
 const selector=document.querySelector('.selector');
 if(selector)selector.scrollLeft=left;
 if(document.querySelector('#viz-filters')&&filterOpen!==undefined)document.querySelector('#viz-filters').open=filterOpen;
 document.querySelector(`[data-action="${action}"]`)?.focus({preventScroll:true});
 window.scrollTo({top,left:window.scrollX,behavior:'instant'});
}
function updateTransform(){const el=document.querySelector('#composition');if(el){el.style.left=viz.transform.x*100+'%';el.style.top=viz.transform.y*100+'%';el.style.width=44*find(viz.plantId).sceneScale*viz.transform.scale+'%';}const range=document.querySelector('#scale'),label=document.querySelector('#scale-label');if(range)range.value=viz.transform.scale;if(label)label.textContent=Math.round(viz.transform.scale*100)+'%';updateSceneLighting(document.querySelector('#canvas > .background'));}
function bindDrag(){const el=document.querySelector('#composition'),parent=document.querySelector('#canvas');let start=null;// Pointer coordinates and image-normalized placement are deliberately separate.
el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);start={clientX:e.clientX,clientY:e.clientY,x:viz.transform.x,y:viz.transform.y};};el.onpointermove=e=>{if(!start)return;const b=parent.getBoundingClientRect();viz.transform.x=Math.max(.05,Math.min(.95,start.x+(e.clientX-start.clientX)/b.width));viz.transform.y=Math.max(.05,Math.min(.95,start.y+(e.clientY-start.clientY)/b.height));updateTransform();};el.onpointerup=el.onpointercancel=()=>start=null;el.onkeydown=e=>{const d={ArrowLeft:[-.02,0],ArrowRight:[.02,0],ArrowUp:[0,-.02],ArrowDown:[0,.02]}[e.key];if(d){e.preventDefault();viz.transform.x=Math.max(.05,Math.min(.95,viz.transform.x+d[0]));viz.transform.y=Math.max(.05,Math.min(.95,viz.transform.y+d[1]));updateTransform();}};}
app.addEventListener('input',e=>{if(e.target.id==='space-name'){pendingName=e.target.value;if(state.pendingSpace)state.pendingSpace.name=pendingName;}if(e.target.id==='search'){const next=structuredClone(state);next.exploreFilters.query=e.target.value;if(commit(next)){document.querySelector('#explore-results').innerHTML=exploreResults();bindGallery();}}if(e.target.id==='viz-search'){const next=structuredClone(state);next.visualizerFilters.query=e.target.value;if(commit(next))refreshVizResults();}if(e.target.id==='scale'){viz.transform.scale=Number(e.target.value);updateTransform();}});
app.addEventListener('change',e=>{if(e.target.id==='photo-file')void uploadFile(e.target.files[0]);if(e.target.id==='pot-color'){potColor=e.target.value;render();}if(e.target.id==='pot-material'){potMaterial=e.target.value;render();}});
app.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const [action,arg,arg2]=target.dataset.action.split(':');let next;
switch(action){
case'intro-page':introIndex=Number(arg);{const slider=document.querySelector('.intro-slides');slider?.scrollTo({left:introIndex*slider.clientWidth,behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}break;case'intro-finish':finishIntro();break;case'browse':next=structuredClone(state);next.introSeen=true;next.signedIn=false;if(commit(next))go('/');break;case'resume-signup':if(state.signupDraft)beginCare('/');break;case'logout':next=structuredClone(state);next.signedIn=false;if(commit(next))go('/');break;
case'back':if(location.hash==='#/profile/care'){exitCare();}else if(history.length>1)history.back();else go('/');break;
case'exit':go('/');break;case'new-space':startNewSpace();break;case'select-space':if(selectSpace(arg))render();break;
case'type':spaceType=arg;next=structuredClone(state);next.pendingSpace={...(next.pendingSpace||{id:newId(),name:''}),type:arg};if(commit(next))render();break;
case'setup-next':{if(state.spaces.length>=4){toast('공간은 최대 4개까지 등록할 수 있어요.');return;}next=structuredClone(state);next.pendingSpace={id:next.pendingSpace?.id||newId(),type:spaceType,name:pendingName.trim()||spaceType};if(commit(next))go('/space/photo');break;}
case'choose-photo':document.querySelector('#photo-file').click();break;case'camera':void capturePhoto();break;
case'space-info':if(selectSpace(arg))go(activeSpace().analysisConfirmed?'/space/detail':'/space/result');break;case'space-photo':if(selectSpace(arg))go('/space/photo');break;case'space-place':if(selectSpace(arg))go('/visualizer/'+plants[0].id);break;
case'rename-space':{const old=state.spaces.find(s=>s.id===arg),name=prompt('공간 이름을 입력해주세요.',old.name);if(name===null)break;if(!name.trim()||name.trim().length>30){toast('공간 이름을 1~30자로 입력해주세요.');break;}next=structuredClone(state);next.spaces.find(s=>s.id===arg).name=name.trim();if(commit(next))render();break;}
case'delete-space':{const old=state.spaces.find(s=>s.id===arg);if(!confirm(`${old.name} 공간과 이 공간의 저장 조합을 삭제할까요?`))break;next=structuredClone(state);next.spaces=next.spaces.filter(s=>s.id!==arg);next.savedCombinations=next.savedCombinations.filter(c=>c.spaceId!==arg);if(next.activeSpaceId===arg)next.activeSpaceId=next.spaces[0]?.id||null;if(commit(next)){viz=null;render();toast('공간을 삭제했어요.');}break;}
case'analyze':if(!photo(uploadSpace())){toast('공간 사진을 먼저 선택해주세요.');return;}analysisController?.abort();analysisJob=null;analysisError='';go('/space/analyzing');break;
case'analysis-manual':editAnalysis=true;go('/space/result');break;case'analysis-edit':editAnalysis=true;render();break;
case'analysis-save':case'analysis-home':case'analysis-recommend':if(saveAnalysis()){if(action==='analysis-recommend')requestRecommendation();else go('/space/detail');}break;
case'recommend':requestRecommendation();break;case'care-edit':if(member())beginCare('/my-page');else go('/auth');break;case'care-exit':exitCare();break;
case'plant-preview':if(expandedCards.get(location.hash)===arg){go('/plants/'+arg);}else if(find(arg)){expandedCards.set(location.hash,arg);renderKeepingPosition('plant-preview:'+arg);}break;
case'care-answer':{
    const entry=questions.find(([key])=>key===arg),value=Number(arg2);
    if(!entry||!(arg==='size'?sizePreferenceValues:entry[2].map((_,i)=>i)).includes(value))break;
    const draft={...answers,[arg]:value};next=structuredClone(state);next.careDraft=draft;
    if(commit(next)){answers=draft;renderKeepingPosition('care-answer:'+arg+':'+value);}break;
}
case'care-submit':if(questions.every(([k])=>answers[k]!=null)){next=structuredClone(state);next.careProfile={...answers};next.careDraft={};next.onboardingSeen=true;if(next.signupDraft&&!member()){next.account={...next.signupDraft,createdAt:new Date().toISOString()};next.signedIn=true;next.signupDraft=null;}if(commit(next)){question=0;answers={};toast('관리 성향을 저장했어요.');if(careDestination==='/recommendations')requestRecommendation();else go(careDestination);}}break;
case'save':next=structuredClone(state);next.savedPlantIds=next.savedPlantIds.includes(arg)?next.savedPlantIds.filter(x=>x!==arg):[...next.savedPlantIds,arg];if(commit(next)){render();toast(state.savedPlantIds.includes(arg)?'식물을 저장했어요.':'저장을 취소했어요.');}break;
case'compare':next=structuredClone(state);if(next.comparePlantIds.includes(arg))next.comparePlantIds=next.comparePlantIds.filter(x=>x!==arg);else{if(next.comparePlantIds.length===3){toast('최대 3개까지 비교할 수 있어요.');return;}next.comparePlantIds.push(arg);}if(commit(next)){render();toast('비교 목록을 변경했어요.');}break;
case'filter':next=structuredClone(state);{const val=['features','types'].includes(arg)?arg2:Number(arg2),list=next.exploreFilters[arg];next.exploreFilters[arg]=list.includes(val)?list.filter(x=>x!==val):[...list,val];}if(commit(next)){const open=document.querySelector('details')?.open;render();if(document.querySelector('details'))document.querySelector('details').open=open;}break;
case'viz-filter':{const open=document.querySelector('#viz-filters')?.open,scroll=document.querySelector('#viz-filters .filter-options')?.scrollTop||0;next=structuredClone(state);const val=['features','types'].includes(arg)?arg2:Number(arg2),list=next.visualizerFilters[arg];next.visualizerFilters[arg]=list.includes(val)?list.filter(v=>v!==val):[...list,val];if(commit(next)){render();document.querySelector('#viz-filters').open=open;const options=document.querySelector('#viz-filters .filter-options');if(options)options.scrollTop=scroll;document.querySelector(`[data-action="viz-filter:${arg}:${arg2}"]`)?.focus({preventScroll:true});}break;}
case'viz-filters-clear':next=structuredClone(state);next.visualizerFilters=fresh().visualizerFilters;if(commit(next))render();break;
case'filters-clear':next=structuredClone(state);next.exploreFilters=fresh().exploreFilters;if(commit(next))render();break;
case'tab':tab=arg;render();break;case'plant-group':plantGroup=arg;render();break;case'viz-plant':viz.plantId=arg;renderSelection('viz-plant:'+arg);break;case'viz-pot':viz.potId=arg;renderSelection('viz-pot:'+arg);break;case'viz-reset':viz.transform={x:.5,y:.65,scale:1};updateTransform();break;
case'scale-down':case'scale-up':viz.transform.scale=Math.min(1.5,Math.max(.5,viz.transform.scale+(action==='scale-up'?.05:-.05)));updateTransform();break;
case'save-combo':next=structuredClone(state);{const c={id:viz.id||newId(),spaceId:viz.spaceId,plantId:viz.plantId,potId:viz.potId,transform:{...viz.transform},createdAt:new Date().toISOString(),placementNeedsReview:false};next.savedCombinations=next.savedCombinations.filter(x=>x.id!==c.id);next.savedCombinations.push(c);}if(commit(next)){viz.id=next.savedCombinations.at(-1).id;toast('조합을 저장했어요.');go('/success');}break;
case'open-combo':{const c=state.savedCombinations.find(c=>c.id===arg);if(selectSpace(c.spaceId)){viz={...structuredClone(c),entry:c.plantId};go('/visualizer/'+c.plantId);}break;}
case'delete-combo':next=structuredClone(state);next.savedCombinations=next.savedCombinations.filter(c=>c.id!==arg);if(commit(next)){render();toast('조합을 삭제했어요.');}break;
}});
function exitCare(){const next=structuredClone(state);next.onboardingSeen=true;next.careDraft=member()?{}:{...answers};if(commit(next)){answers={};question=0;go(careDestination==='/my-page'?'/my-page':'/');}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
location.hash=state.introSeen?'/':'/intro';render();
setTimeout(()=>{splashVisible=false;render();},1900);


