// Native touch/trackpad scrolling plus mouse grab-to-scroll; a drag never selects a card.
function bindHorizontalScroll(el,snap=false){if(!el)return;let start=null,dragged=false,blockClickUntil=0;
 el.addEventListener('dragstart',e=>e.preventDefault());
 el.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;start={x:e.clientX,left:el.scrollLeft,id:e.pointerId};dragged=false;});
 el.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x;if(!dragged&&Math.abs(dx)>6){dragged=true;el.setPointerCapture(e.pointerId);el.classList.add('dragging');}if(dragged){e.preventDefault();el.scrollLeft=start.left-dx;}});
 const end=e=>{if(!start)return;const wasDragged=dragged;start=null;el.classList.remove('dragging');if(el.hasPointerCapture?.(e.pointerId))el.releasePointerCapture(e.pointerId);if(wasDragged){blockClickUntil=Date.now()+350;if(snap)el.scrollTo({left:Math.round(el.scrollLeft/el.clientWidth)*el.clientWidth,behavior:'smooth'});}};
 el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('pointerleave',e=>{if(!dragged)start=null;});
 el.addEventListener('click',e=>{if(Date.now()<blockClickUntil){e.preventDefault();e.stopPropagation();}},true);
}
function bindIntro(){const el=document.querySelector('.intro-slides');if(!el)return;el.scrollLeft=introIndex*el.clientWidth;bindHorizontalScroll(el,true);
 el.addEventListener('scroll',()=>{introIndex=Math.max(0,Math.min(2,Math.round(el.scrollLeft/el.clientWidth)));document.querySelectorAll('.intro-dots button').forEach((b,i)=>{b.classList.toggle('active',i===introIndex);b.setAttribute('aria-current',i===introIndex?'step':'false');});},{passive:true});
 el.addEventListener('keydown',e=>{if(e.target!==el||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();introIndex=Math.max(0,Math.min(2,introIndex+(e.key==='ArrowRight'?1:-1)));el.scrollTo({left:introIndex*el.clientWidth,behavior:'smooth'});});
}

// Local, bounded photo matching. No inferred depth, room dimensions or remote call.
function sceneTone(r,g,b,left,right){
    const luminance=(.2126*r+.7152*g+.0722*b)/255;
    const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
    return {
        brightness:clamp(.67+luminance*.50,.76,1.04),
        saturation:clamp(.78+luminance*.15,.78,.93),
        contrast:.94,
        warmth:clamp((r-b)/255*.45,0,.14),
        cool:clamp((b-r)/255*.3,0,.07),
        shadowX:clamp((left-right)/255*42,-16,16),
        shadowOpacity:clamp(.16+luminance*.09,.16,.25)
    };
}

function sampleScene(data,width,height,x,y){
    const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
    const cx=clamp(x,0,1)*(width-1),cy=clamp(y,0,1)*(height-1);
    const samples=[];
    let left=0,right=0,nl=0,nr=0;
    for(let py=Math.max(0,Math.floor(cy-height*.13));py<=Math.min(height-1,Math.ceil(cy+height*.07));py++){
        for(let px=Math.max(0,Math.floor(cx-width*.20));px<=Math.min(width-1,Math.ceil(cx+width*.20));px++){
            const i=(py*width+px)*4;
            if(data[i+3]<128)continue;
            const rgb=[data[i],data[i+1],data[i+2]],l=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];
            samples.push({rgb,l});
            if(px<cx){left+=l;nl++;}else{right+=l;nr++;}
        }
    }
    if(!samples.length)return null;
    // Keep isolated dark seams and reflected highlights from tinting the whole plant.
    samples.sort((a,b)=>a.l-b.l);
    const trim=Math.floor(samples.length*.1),middle=samples.slice(trim,samples.length-trim);
    const sum=middle.reduce((a,p)=>a.map((v,i)=>v+p.rgb[i]),[0,0,0]);
    const mean=sum.map(v=>v/middle.length),light=.2126*mean[0]+.7152*mean[1]+.0722*mean[2];
    return sceneTone(...mean,nl?left/nl:light,nr?right/nr:light);
}

function updateSceneLighting(img){
    const pixels=img&&scenePixels.get(img);
    if(!pixels)return;
    const compositionEl=img.parentElement.querySelector('.composition');
    if(!compositionEl)return;
    const bounds=img.getBoundingClientRect(),placed=compositionEl.getBoundingClientRect();
    if(!bounds.width||!bounds.height)return;
    const ground=parseFloat(compositionEl.style.getPropertyValue('--ground-top'))/100;
    const center=parseFloat(compositionEl.style.getPropertyValue('--ground-center'))/100;
    const x=(placed.left+placed.width*center-bounds.left)/bounds.width;
    const y=(placed.top+placed.height*ground-bounds.top)/bounds.height;
    const tone=sampleScene(pixels.data,pixels.width,pixels.height,x,y);
    if(!tone)return;
    for(const [name,value] of Object.entries(tone)){
        const key={shadowX:'shadow-x',shadowOpacity:'shadow-opacity'}[name]||'scene-'+name;
        compositionEl.style.setProperty('--'+key,value+(name==='shadowX'?'%':''));
    }
}

function bindSceneLighting(){
    document.querySelectorAll('.canvas > .background').forEach(img=>{
        const apply=()=>{
            try{
                const c=document.createElement('canvas');c.width=64;c.height=64;
                const ctx=c.getContext('2d',{willReadFrequently:true});
                ctx.drawImage(img,0,0,64,64);
                scenePixels.set(img,ctx.getImageData(0,0,64,64));
                updateSceneLighting(img);
            }catch{/* Image/CORS failures keep the neutral CSS treatment. */}
        };
        if(img.complete&&img.naturalWidth)apply();else img.addEventListener('load',apply,{once:true});
    });
}


function bindVerticalGallery(grid){let start=null,dragged=false,blocked=0;grid.addEventListener('dragstart',e=>e.preventDefault());grid.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('.gallery-actions,.gallery-tools'))return;start={y:e.clientY,top:window.scrollY};dragged=false;});grid.addEventListener('pointermove',e=>{if(!start)return;const dy=e.clientY-start.y;if(Math.abs(dy)>6&&!dragged){dragged=true;grid.setPointerCapture(e.pointerId);}if(dragged){e.preventDefault();window.scrollTo({top:start.top-dy,behavior:'instant'});}});const end=e=>{if(dragged)blocked=Date.now()+350;start=null;dragged=false;if(grid.hasPointerCapture?.(e.pointerId))grid.releasePointerCapture(e.pointerId);};grid.addEventListener('pointerup',end);grid.addEventListener('pointercancel',end);grid.addEventListener('pointerleave',()=>{if(!dragged)start=null;});grid.addEventListener('click',e=>{if(Date.now()<blocked){e.preventDefault();e.stopPropagation();}},true);}
